export function getHeroTitle(slug: string, kind: "location" | "service") {
  const title = kind === "location" ? locationHeroTitles[slug] : serviceHeroTitles[slug];
  if (!title) throw new Error(`Missing hero title for ${kind}: ${slug}`);
  return title;
}

